Lemma farm_sound_0RB0RB_0LC1RD_1RB1LC_1RB1RA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_0RB0RB_0LC1RD_1RB1LC_1RB1RA r ph).
