Lemma farm_rhs_0RB0RB_0LC1RD_1RB1LC_1RB1RA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_rhs (farm_0RB0RB_0LC1RD_1RB1LC_1RB1RA r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_0RB0RB_0LC1RD_1RB1LC_1RB1RA r ph)
                      (astride 1 1 r) (fm2_0RB0RB_0LC1RD_1RB1LC_1RB1RA r ph)
                      (f_to (fam_fill FAM ph))
                      (f_pre (fam_fill FAM ph)) (f_suf (fam_fill FAM ph))).
