Lemma farm_sound_0RB0RB_1LC1RB_1LD0LA_0RB0LC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_0RB0RB_1LC1RB_1LD0LA_0RB0LC r ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
