    { eapply arm_sound; [exact rules_sound_0RB0RB_1LC1RB_1LD0LA_0RB0LC | exact ok_farm1_0_0RB0RB_1LC1RB_1LD0LA_0RB0LC]. }
    exfalso; lia.
  }
