Qed.

Lemma farm_lhs_0RB0RB_1LC1RB_1LD0LA_0RB0LC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_lhs (farm_0RB0RB_1LC1RB_1LD0LA_0RB0LC r ph)
    = cls_conf FAM (run_side FAM (fm_b FAM - 1) r (astride 1 1 r)
                      0 ph [] []).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
