Lemma farm_rhs_0RB0RB_1LC1RB_1LD0LA_0RB0LC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_0RB0RB_1LC1RB_1LD0LA_0RB0LC r ph)
                  (astride 1 1 r) (fm2_0RB0RB_1LC1RB_1LD0LA_0RB0LC r ph)
                  (f_to (fam_fill FAM ph))
                  (f_pre (fam_fill FAM ph)) (f_suf (fam_fill FAM ph)))
