(** ** What this board establishes

    52 of 52 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 52 of them
    collapse to 3 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB : LRule :=
  mkLRule (mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 [])) 6 4.
Definition ch_iarm0_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB : list rstep := [RB (SRotL 1);RB (SWin 1);RB (SCycL 3 0);RB (SWin 2);RB (SCycR 3);RB (SWin 1);RB (SUnrotL 1)].
Lemma ok_iarm0_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB :
  check_arm tm false true rules iarm0_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB
            ch_iarm0_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_0RB0RD_0LC1RA_1RD1LC_1LC1RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB
  | _, _ => iarm0_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB : LRule :=
  mkLRule (mkC StB (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1;S1;S1;S1;S1]) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S1;S0;S1;S1;S1;S1] [S1;S0;S1] 1 0 [S1;S0;S1;S1;S1]) S0 (mkS [] [] 0 0 [])) 6 30.
Definition ch_farm1_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB : list rstep := [RB (SWin 3);RB (SCycL 3 0);RB (SWin 5);RB (SWinL 7);RB (SCycR 3);RB (SWin 3);RB (SWinR 12);RB (SRotL 1)].
Lemma ok_farm1_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB :
  check_arm tm true true rules farm1_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB
            ch_farm1_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB = true.
Proof. vm_compute. reflexivity. Qed.

