  mkLRule (mkC StB (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1;S0;S1;S1;S1]) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S1;S0;S1] [S1;S0;S1] 1 0 [S1;S1;S1;S1;S1]) S0 (mkS [] [] 0 0 [])) 6 10.
Definition ch_farm1_1_0RB0RD_0LC1RA_1RD1LC_1LC1RB : list rstep := [RB (SWin 3);RB (SCycL 3 0);RB (SWin 4);RB (SCycR 3);RB (SWin 3)].
Lemma ok_farm1_1_0RB0RD_0LC1RA_1RD1LC_1LC1RB :
  check_arm tm true true rules farm1_1_0RB0RD_0LC1RA_1RD1LC_1LC1RB
            ch_farm1_1_0RB0RD_0LC1RA_1RD1LC_1LC1RB = true.
Proof. vm_compute. reflexivity. Qed.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_0RB0RD_0LC1RA_1RD1LC_1LC1RB (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB
  | 1, 1 => farm1_1_0RB0RD_0LC1RA_1RD1LC_1LC1RB
  | _, _ => farm1_0_0RB0RD_0LC1RA_1RD1LC_1LC1RB  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_0RB0RD_0LC1RA_1RD1LC_1LC1RB (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 1, 1 => 1 | _, _ => 0 end.
Definition fm2_0RB0RD_0LC1RA_1RD1LC_1LC1RB (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 1, 1 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_0RB0RD_0LC1RA_1RD1LC_1LC1RB (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 3;SCycL 3 0;SWin 5;SWinL 7;SCycR 3;SWin 3]
  | 1, (StA, S1) => [SWin 3;SCycL 3 0;SWinL 9]
  | 1, (StB, S0) => []
  | 1, (StB, S1) => [SWin 3;SCycL 3 0;SWinL 8]
  | 1, (StC, S0) => [SWin 3;SCycL 3 0;SWinL 6]
  | 1, (StC, S1) => [SWin 1]
  | 1, (StD, S0) => [SWin 3;SCycL 3 0;SWin 5;SWinL 7;SCycR 3;SWinR 6]
  | 1, (StD, S1) => [SWin 3;SCycL 3 0;SWinL 7]
  | _, _ => []
  end.

